import React from 'react';
import {
  MicIcon,
  MicOffIcon,
  VideoIcon,
  VideoOffIcon,
  PhoneOffIcon,  // ✅ CHANGED FROM PhoneIcon
  ScreenShareIcon,
} from './Icons';

export const CallControls = ({
  isMuted,
  setIsMuted,
  isVideoOff,
  setIsVideoOff,
  isScreenSharing,
  toggleScreenShare,
  sendReaction,
  isRecording,
  setIsRecording,
  onEndCall,
}) => {
  return (
    <div className="flex items-center gap-3 bg-gray-900/90 backdrop-blur-lg px-6 py-4 rounded-full shadow-2xl border border-gray-700">
      {/* Microphone */}
      <button
        onClick={() => setIsMuted(!isMuted)}
        className={`p-4 rounded-full transition-all ${
          isMuted
            ? 'bg-red-600 hover:bg-red-700'
            : 'bg-gray-700 hover:bg-gray-600'
        }`}
        title={isMuted ? 'Unmute' : 'Mute'}
      >
        {isMuted ? (
          <MicOffIcon className="w-6 h-6 text-white" />
        ) : (
          <MicIcon className="w-6 h-6 text-white" />
        )}
      </button>

      {/* Video */}
      <button
        onClick={() => setIsVideoOff(!isVideoOff)}
        className={`p-4 rounded-full transition-all ${
          isVideoOff
            ? 'bg-red-600 hover:bg-red-700'
            : 'bg-gray-700 hover:bg-gray-600'
        }`}
        title={isVideoOff ? 'Turn on camera' : 'Turn off camera'}
      >
        {isVideoOff ? (
          <VideoOffIcon className="w-6 h-6 text-white" />
        ) : (
          <VideoIcon className="w-6 h-6 text-white" />
        )}
      </button>

      {/* Screen Share */}
      <button
        onClick={toggleScreenShare}
        className={`p-4 rounded-full transition-all ${
          isScreenSharing
            ? 'bg-blue-600 hover:bg-blue-700'
            : 'bg-gray-700 hover:bg-gray-600'
        }`}
        title={isScreenSharing ? 'Stop sharing' : 'Share screen'}
      >
        <ScreenShareIcon className="w-6 h-6 text-white" />
      </button>

      {/* Reactions */}
      <div className="flex gap-2 px-3 border-l border-r border-gray-700">
        {['👍', '❤️', '🎉', '😂'].map((emoji) => (
          <button
            key={emoji}
            onClick={() => sendReaction(emoji)}
            className="text-2xl hover:scale-125 transition-transform"
          >
            {emoji}
          </button>
        ))}
      </div>

      {/* Record */}
      <button
        onClick={() => setIsRecording(!isRecording)}
        className={`p-4 rounded-full transition-all ${
          isRecording
            ? 'bg-red-600 hover:bg-red-700 animate-pulse'
            : 'bg-gray-700 hover:bg-gray-600'
        }`}
        title={isRecording ? 'Stop recording' : 'Start recording'}
      >
        <div className="w-6 h-6 flex items-center justify-center">
          {isRecording ? (
            <div className="w-4 h-4 bg-white rounded-sm"></div>
          ) : (
            <div className="w-5 h-5 bg-white rounded-full"></div>
          )}
        </div>
      </button>

      {/* End Call - ✅ USING PhoneOffIcon */}
      <button
        onClick={onEndCall}
        className="p-4 bg-red-600 hover:bg-red-700 rounded-full transition-all ml-2"
        title="End call"
      >
        <PhoneOffIcon className="w-6 h-6 text-white" />
      </button>
    </div>
  );
};
